CREATE TABLE pipeline_runs(job_id TEXT PRIMARY KEY REFERENCES jobs(job_id),config_revision TEXT NOT NULL,snapshot TEXT NOT NULL);
CREATE TABLE pipeline_processing_snapshots(job_id TEXT PRIMARY KEY REFERENCES jobs(job_id),config_revision TEXT NOT NULL,snapshot TEXT NOT NULL);
CREATE TABLE pipeline_steps(job_id TEXT NOT NULL REFERENCES jobs(job_id),item_uid TEXT NOT NULL REFERENCES items,revision_uid TEXT NOT NULL REFERENCES item_revisions,stage TEXT NOT NULL CHECK(stage IN ('PROCESS','EMBED')),state TEXT NOT NULL CHECK(state IN ('SUCCEEDED','FAILED')),result_uid TEXT REFERENCES processing_results,error_code TEXT,PRIMARY KEY(job_id,item_uid,stage));
CREATE TABLE pipeline_replays(replay_key TEXT PRIMARY KEY,job_id TEXT NOT NULL UNIQUE REFERENCES jobs(job_id),original_job_id TEXT NOT NULL REFERENCES jobs(job_id),source_item_id TEXT NOT NULL,item_uid TEXT REFERENCES items,revision_uid TEXT REFERENCES item_revisions,failed_stage TEXT NOT NULL,from_stage TEXT NOT NULL,config_fingerprint TEXT NOT NULL);
CREATE TRIGGER pipeline_snapshot_immutable BEFORE UPDATE ON pipeline_runs BEGIN SELECT RAISE(ABORT,'pipeline snapshot immutable'); END;
CREATE TRIGGER pipeline_processing_immutable BEFORE UPDATE ON pipeline_processing_snapshots BEGIN SELECT RAISE(ABORT,'pipeline processing snapshot immutable'); END;
CREATE TRIGGER pipeline_step_owner BEFORE INSERT ON pipeline_steps WHEN NOT EXISTS(SELECT 1 FROM jobs j JOIN items i ON i.project_uid=j.project_uid JOIN item_revisions r ON r.item_uid=i.item_uid WHERE j.job_id=NEW.job_id AND i.item_uid=NEW.item_uid AND r.revision_uid=NEW.revision_uid) BEGIN SELECT RAISE(ABORT,'pipeline step ownership mismatch'); END;
